<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,provide} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {practiceSelectionContextKey} from '@/practice/selection-context'
import {usePracticeAttempt} from '@/stores/practice-attempt'
import {ApiError} from '@/api/client'
import {retryPracticeMistakes} from '@/api/practice'
import {errorMessage} from '@/api/identity'
import {getGeneration} from '@/auth/token-session'
import {useAuthDialogStore} from '@/stores/auth-dialog'
import PracticeListeningPlayer from '@/components/practice/PracticeListeningPlayer.vue'
import PracticeMatchPlayer from '@/components/practice/PracticeMatchPlayer.vue'
import PracticeClozePlayer from '@/components/practice/PracticeClozePlayer.vue'
import PracticeReader from '@/components/practice/PracticeReader.vue'
import PracticeQuestions from '@/components/practice/PracticeQuestions.vue'
import PracticeResult from '@/components/practice/PracticeResult.vue'
import {retryPaperMistakes} from '@/api/practice-paper'
import '@/styles/practice.css'
const route=useRoute(),router=useRouter(),store=usePracticeAttempt(),login=useAuthDialogStore(),mobileTab=ref('questions'),focused=ref(false),fontSize=ref('20'),lineHeight=ref('1.9'),error=ref(''),busy=ref(false);let retryId='',disposed=false
provide(practiceSelectionContextKey,computed(()=>({practiceAttemptId:store.attempt?.id,enabled:true})))
const activeReview=ref('')
const paperMistakesDestination=computed(()=>{const url=new URL(destination.value,window.location.origin);return url.searchParams.get('section')==='paper'&&url.searchParams.get('tab')==='mistakes'?destination.value:'/practice/cet?exam=CET4&source=PAST&collection=PAST&section=paper&tab=mistakes'})
const listeningPlayer=ref<InstanceType<typeof PracticeListeningPlayer>>()
const isListening=computed(()=>store.attempt?.readingType==='LISTENING')
const isMatch=computed(()=>store.attempt?.readingType==='MATCH'||store.attempt?.questions[0]?.type==='MATCH')
const isCloze=computed(()=>store.attempt?.readingType==='CLOZE'||store.attempt?.questions[0]?.type==='CLOZE')
const destination=computed(()=>{const p=String(route.query.returnTo||'');return (/^\/practice\/(?:cet4|cet|postgraduate)(?:\?|$)/.test(p)||/^\/practice(?:\?|$)/.test(p))?p:store.attempt?.reviewSource?'/practice/cet?exam=CET4&source=PAST&collection=PAST&section=paper&tab=mistakes':'/practice/cet'})
async function submit(){listeningPlayer.value?.pause();if(!await store.flush())return;const remaining=store.attempt?.questions.filter(q=>!store.choices[q.id]).length||0;try{await ElMessageBox.confirm(remaining?`还有 ${remaining} 题未答，交卷后按错题计入。是否确认交卷？`:'交卷后不能修改本轮答案，确认提交整组练习？','确认交卷',{confirmButtonText:'确认交卷',cancelButtonText:'返回检查',autofocus:false})}catch{return}await store.submit(remaining>0)}
async function exit(){listeningPlayer.value?.pause();if(store.pendingSubmit){error.value='上次交卷结果尚未确认，请先重试交卷。';return}if(await store.flush())await router.push(destination.value)}
async function leave(){listeningPlayer.value?.pause();if(store.submitting||busy.value)return false;if(store.pendingSubmit){error.value='交卷结果尚未确认，请先重试交卷。';return false}if(!store.dirty)return true;if(await store.flush())return true;try{await ElMessageBox.confirm('保存尚未成功。继续离开将放弃本地未确认的选择，服务器已保存部分仍保留。','保存未完成',{confirmButtonText:'放弃本地选择并离开',cancelButtonText:'留在这里重试',autofocus:false});store.discardLocal();return true}catch{return false}}
async function retry(){if(!store.attempt||busy.value)return;const g=getGeneration(),id=store.attempt.id;retryId||=crypto.randomUUID();busy.value=true;error.value='';activeReview.value='';try{const source=store.attempt.reviewSource;const t=await (source?retryPaperMistakes(source.attemptId,{requestId:retryId,slot:source.slot}):retryPracticeMistakes(id,retryId));if(!disposed&&g===getGeneration()){retryId='';busy.value=false;await router.push({path:'/practice/attempts/'+t.id,query:{returnTo:destination.value}})}}catch(e){if(!disposed&&g===getGeneration()){error.value=errorMessage(e);const id=e instanceof ApiError?e.fieldErrors?.activeAttemptId:undefined;if(id&&/^\d+$/.test(id))activeReview.value=id}}finally{if(!disposed)busy.value=false}}
function unload(e:BeforeUnloadEvent){if(store.dirty||store.pendingSubmit){e.preventDefault();e.returnValue=''}}
watch(()=>route.params.id,()=>{retryId='';activeReview.value='';void store.load(String(route.params.id))},{immediate:true});onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{disposed=true;store.dispose();window.removeEventListener('beforeunload',unload)})
</script>
<template><section class="practice-page practice-study-attempt" :class="{'practice-reader-focus':focused}" :style="{'--practice-reading-size':fontSize+'px','--practice-reading-line':lineHeight}"><header class="practice-heading"><div><h1>{{store.attempt?.title||'专项练习'}}</h1><p>{{store.attempt?.kind==='MISTAKES'?'错题重做 · 沿用原轮次的材料和题目版本':(isListening?'整套听力 · 整套交卷后查看原文与解析':isMatch?'长篇匹配 · 每题对应一个段落，同一段可重复选择':isCloze?'选词填空 · 10空共享15词，整组交卷后查看解析':'仔细阅读 · 整组交卷后查看答案解析')}}</p></div><button :disabled="store.submitting||busy" @click="exit">{{store.attempt?.status==='COMPLETED'?'返回题库':'退出并保存'}}</button></header><p v-if="store.loading" role="status">正在加载已保存练习…</p><div v-if="store.error||error" class="practice-notice practice-error" role="alert"><p>{{store.error||error}}</p><button v-if="store.pendingSubmit" :disabled="store.submitting" @click="store.submit(store.pendingSubmit.confirmUnanswered)">重试交卷</button><button v-else-if="store.conflict" @click="store.reloadKeepingChoices()">加载最新记录并保留选择</button><button v-else :disabled="store.saving" @click="store.dirty?store.flush():store.load(String(route.params.id))">{{store.dirty?'重试保存':'重新加载'}}</button><button @click="login.request(route.fullPath)">重新验证登录</button></div><RouterLink v-if="activeReview" :to="{path:'/practice/attempts/'+activeReview,query:{returnTo:destination}}">继续已有错题练习</RouterLink><template v-if="store.attempt"><div v-if="store.attempt.reviewSource" class="practice-notice paper-review-source"><p>来自整卷 · 按原卷题号复习，订正不会改变原卷成绩。</p><RouterLink :to="{path:'/practice/paper-attempts/'+store.attempt.reviewSource.attemptId,query:{slot:store.attempt.reviewSource.slot,questionId:store.currentQuestionId,returnTo:destination}}">查看原卷</RouterLink><RouterLink :to="paperMistakesDestination">返回整卷错题本</RouterLink></div><div class="practice-toolbar"><p role="status" class="practice-hint">{{store.attempt.status==='COMPLETED'?'本轮已交卷，成绩已保存':store.saveState}}</p><button v-if="store.attempt.status==='IN_PROGRESS'" class="button-primary" :disabled="store.submitting||!!store.pendingSubmit" @click="submit">整组交卷</button></div><div v-if="!isListening" class="practice-reading-tools"><details class="practice-reading-settings"><summary>阅读设置</summary><div><label>正文字号<select v-model="fontSize"><option value="18">较小</option><option value="20">标准</option><option value="22">较大</option></select></label><label>正文行距<select v-model="lineHeight"><option value="1.7">紧凑</option><option value="1.9">舒适</option><option value="2.1">宽松</option></select></label></div></details><button class="practice-focus-button" :aria-pressed="focused" @click="focused=!focused">{{focused?'返回答题':'专注原文'}}</button></div><PracticeListeningPlayer ref="listeningPlayer" v-if="isListening" :attempt="store.attempt" :choices="store.choices" :flags="store.flags" :current-id="store.currentQuestionId" :playback="store.playback" :disabled="store.submitting||!!store.pendingSubmit||store.conflict" @change="store.chooseBatch" @navigate="store.navigate" @playback="store.updatePlayback"/><PracticeMatchPlayer v-else-if="isMatch" :attempt="store.attempt" :choices="store.choices" :flags="store.flags" :current-id="store.currentQuestionId" :disabled="store.submitting||!!store.pendingSubmit||store.conflict" @change="store.chooseBatch" @navigate="store.navigate" @submit="submit"/><PracticeClozePlayer v-else-if="isCloze" :attempt="store.attempt" :choices="store.choices" :current-id="store.currentQuestionId" :disabled="store.submitting||!!store.pendingSubmit||store.conflict" @change="store.chooseBatch" @navigate="store.navigate" @submit="submit"/><div v-if="(isCloze||isMatch||isListening)&&store.attempt.status==='COMPLETED'" class="practice-actions"><button :disabled="busy||store.attempt.correctCount===store.attempt.total" @click="retry">{{isListening?'重练整套听力':isMatch?'重练本组（含错题）':'重练本组（含错空）'}}</button></div><template v-if="!isCloze&&!isMatch&&!isListening"><div class="practice-mobile-tabs"><button :aria-pressed="mobileTab==='article'" @click="mobileTab='article'">阅读原文</button><button :aria-pressed="mobileTab==='questions'" @click="mobileTab='questions'">{{store.attempt.status==='COMPLETED'?'成绩解析':'答题'}}</button></div><div class="practice-workspace" :data-mobile-tab="mobileTab"><section class="practice-panel practice-reading-panel"><PracticeReader :article="store.attempt.article"/></section><PracticeQuestions v-if="store.attempt.status==='IN_PROGRESS'" :questions="store.attempt.questions" :original-numbers="store.attempt.reviewSource?.originalNumbers" :current-id="store.currentQuestionId" :choices="store.choices" :disabled="store.submitting||!!store.pendingSubmit" @choose="store.choose" @navigate="store.navigate"/><div v-else class="practice-answer-panel"><PracticeResult :attempt="store.attempt" :busy="busy" @retry="retry"/></div></div></template></template></section></template>
